 "content": "def transform(grid):
    """Replace color-3 cells with their horizontal mirror values."""
    out = [row[:] for row in grid]
    width = len(grid[0])
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value == 3:
                out[r][c] = row[width - 1 - c]
    return out
